    .replace(/\r/g, '')
    .split(/\n\s*\n/)
    .map((b) => b.trim())
    .filter((b) => b !== '');
  const heading = title
    ? '<tr><td style="padding:28px 28px 0"><h1 style="margin:0 0 4px;font-family:' + SERIF + ';font-size:26px;font-weight:400;line-height:1.2;color:' + BRAND.ink + '">' + esc(title) + '</h1></td></tr>'
