    'Where: ' + f.address,
    'Fee: ' + bookFeeText(area),
    'Reference: ' + row.bookingRef,
    '',
    'Please bring:'
  ].concat(area.bring.map((x) => '- ' + x), [
    '',
    f.language.noConfidential,
    '',
