  const load = (att) => rows.filter((r) => bookIsBooked(r) && r.attorney === att && bookRowSpan(r).e > nowMs).length;
  const attorney = free.slice().sort((a, b) => load(a) - load(b) || area.attorneys.indexOf(a) - area.attorneys.indexOf(b))[0];
