// Design system v2 (brand/tokens.css). Mail clients do not load web fonts, so the heading falls back to Georgia.
const BRAND = { bg: '#0b0b0c', card: '#121214', line: '#26262b', ink: '#f5f3ee', muted: '#a8a6a0', brass: '#d4a94f' };
